157	    const online = await checkHealth();
158	    if (online) {
159	      statusBarItem.text = '$(check) Polyglot';
160	      statusBarItem.tooltip = 'Polyglot is running';
161	    } else {
162	      statusBarItem.text = '$(warning) Polyglot';
163	      statusBarItem.tooltip = 'Polyglot is not reachable — click to retry';
164	      statusBarItem.color = new vscode.ThemeColor('problemsWarningIcon.foreground');
165	    }
166	    statusBarItem.show();
167	  }
168	}
