170	function formatRunDetail(detail: RunDetail): string {
171	  const d = detail;
172	
173	  let md = `# Run: ${d.orchestrationName ?? 'Unknown'}\n\n`;
174	  md += `**Task:** ${d.task ?? ''}\n\n`;
175	  md += `**Status:** ${d.status ?? ''}\n`;
176	  md += `**Started:** ${d.startedAt ?? ''}\n`;
177	  md += `**Duration:** ${d.duration ? Math.round(d.duration / 1000) + 's' : '?'}\n`;
178	  md += `**Nodes:** ${d.nodeCount ?? 0}\n\n`;
179	  md += `---\n\n`;
180	
181	  if (d.logs && Array.isArray(d.logs)) {
182	    md += `## Run Log\n\n`;
183	    for (const log of d.logs) {
184	      md += `### ${log.label ?? 'Node'} (${log.type ?? ''})\n\n`;
185	      if (log.output) md += `\`\`\`\n${log.output}\n\`\`\`\n\n`;
186	      if (log.error) md += `**Error:** ${log.error}\n\n`;
187	    }
188	  }
189	
190	  if (d.outputs && typeof d.outputs === 'object') {
191	    md += `## Node Outputs\n\n`;
192	    for (const [nodeId, output] of Object.entries(d.outputs)) {
193	      md += `### ${nodeId}\n\n\`\`\`\n${output}\n\`\`\`\n\n`;
194	    }
195	  }
196	
197	  return md;
198	}
